<x-layouts.crm title="Empresas" eyebrow="Relacionamento">
    <section class="mx-auto max-w-[1440px] px-4 py-8 sm:px-6 lg:px-8" data-crm-companies data-api-base="{{ $crmApiBase }}" data-directory-api-base="{{ $crmDirectoryApiBase }}">
        <div class="flex justify-end">
            <button type="button" data-company-open-form class="inline-flex min-h-11 items-center justify-center rounded-lg bg-slate-900 px-5 text-sm font-bold text-white transition hover:bg-slate-700 focus:outline-none focus:ring-2 focus:ring-brand-500 focus:ring-offset-2">+ Nova empresa</button>
        </div>
        <div class="mt-8 rounded-2xl border border-slate-200 bg-white p-4 shadow-[0_5px_10px_rgba(2,2,76,0.02)] sm:p-5"><form class="flex flex-col gap-3 sm:flex-row" data-company-search><label class="sr-only" for="company-search">Buscar empresas</label><input id="company-search" name="search" type="search" placeholder="Buscar por nome, razão social ou e-mail" class="min-h-11 flex-1 rounded-lg border border-slate-300 px-4 text-sm outline-none transition placeholder:text-slate-400 focus:border-brand-500 focus:ring-2 focus:ring-brand-100"><button type="submit" class="min-h-11 rounded-lg border border-slate-300 px-5 text-sm font-bold text-slate-700 hover:border-brand-300 hover:bg-brand-50 hover:text-brand-700">Buscar</button></form></div>
        <div class="mt-4 hidden" data-company-feedback role="status"></div>
        <div class="mt-4" data-company-list-state="loading" aria-busy="true" aria-label="Carregando empresas"><div class="h-64 animate-pulse rounded-2xl border border-slate-200 bg-slate-100"></div></div>
        <div class="mt-4 hidden" data-company-list-state="error" role="alert"><div class="rounded-2xl border border-red-200 bg-red-50 p-6 text-red-800"><h2 class="font-bold">Não foi possível carregar as empresas</h2><p class="mt-2 text-sm" data-company-error></p><button type="button" data-company-retry class="mt-4 rounded-lg bg-red-700 px-4 py-2 text-sm font-bold text-white hover:bg-red-800">Tentar novamente</button></div></div>
        <div class="mt-4 hidden" data-company-list-state="content"><div class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_5px_10px_rgba(2,2,76,0.02)]"><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><caption class="sr-only">Lista de empresas</caption><thead class="border-b border-slate-200 bg-slate-50 text-xs uppercase tracking-[0.08em] text-slate-500"><tr><th scope="col" class="px-5 py-4 font-bold">Empresa</th><th scope="col" class="px-5 py-4 font-bold">Razão social</th><th scope="col" class="px-5 py-4 font-bold">E-mail</th><th scope="col" class="px-5 py-4 font-bold">Telefone</th><th scope="col" class="px-5 py-4 text-right font-bold">Ações</th></tr></thead><tbody data-company-rows class="divide-y divide-slate-100"></tbody></table></div><div class="flex flex-col gap-3 border-t border-slate-100 px-5 py-4 text-sm text-slate-500 sm:flex-row sm:items-center sm:justify-between"><span data-company-summary></span><div class="flex gap-2"><button type="button" data-company-prev class="rounded-lg border border-slate-200 px-3 py-2 font-semibold hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40">Anterior</button><button type="button" data-company-next class="rounded-lg border border-slate-200 px-3 py-2 font-semibold hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40">Próxima</button></div></div></div></div>
        <dialog data-company-dialog class="w-[min(100%-2rem,62rem)] rounded-2xl border border-slate-200 p-0 shadow-2xl backdrop:bg-slate-900/30"><form method="dialog" data-company-form class="max-h-[90vh] overflow-y-auto p-6 sm:p-8"><div class="flex items-start justify-between gap-4"><div><p class="text-sm font-bold uppercase tracking-[0.12em] text-accent-600">Cadastro</p><h2 class="mt-1 text-2xl font-bold text-slate-900" data-company-form-title>Adicionar empresa</h2><p class="mt-2 text-sm text-slate-500">Os campos marcados com * são obrigatórios.</p></div><button type="button" data-company-close aria-label="Fechar formulário" class="rounded-lg p-2 text-xl leading-none text-slate-500 hover:bg-slate-100">×</button></div>
            <div class="mt-7 grid gap-6"><section><h3 class="border-b border-slate-200 pb-2 text-lg font-bold text-slate-800">Dados cadastrais</h3><div class="mt-4 grid gap-4 sm:grid-cols-2"><div><label for="company-name" class="mb-1 block text-sm font-semibold text-slate-700">Nome da empresa <span class="text-red-600">*</span></label><input id="company-name" name="name" required maxlength="180" class="min-h-11 w-full rounded-lg border border-slate-300 px-3 outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-100"></div><div><label for="company-legal-name" class="mb-1 block text-sm font-semibold text-slate-700">Razão social</label><input id="company-legal-name" name="legal_name" maxlength="255" class="min-h-11 w-full rounded-lg border border-slate-300 px-3 outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-100"></div><div><label for="company-document" class="mb-1 block text-sm font-semibold text-slate-700">CNPJ</label><input id="company-document" name="document" inputmode="numeric" maxlength="18" placeholder="00.000.000/0000-00" class="min-h-11 w-full rounded-lg border border-slate-300 px-3 outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-100"></div><input type="hidden" name="document_type" value="cnpj"><div><label for="company-email" class="mb-1 block text-sm font-semibold text-slate-700">E-mail</label><input id="company-email" name="email" type="email" maxlength="255" class="min-h-11 w-full rounded-lg border border-slate-300 px-3 outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-100"></div><div><label for="company-phone" class="mb-1 block text-sm font-semibold text-slate-700">Telefone</label><input id="company-phone" name="phone" maxlength="40" class="min-h-11 w-full rounded-lg border border-slate-300 px-3 outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-100"></div></div></section>
                <section><h3 class="border-b border-slate-200 pb-2 text-lg font-bold text-slate-800">Endereço</h3><div class="mt-4 grid gap-4 sm:grid-cols-4"><div><label for="company-postal-code" class="mb-1 block text-sm font-semibold text-slate-700">CEP</label><input id="company-postal-code" name="postal_code" inputmode="numeric" maxlength="9" placeholder="00000-000" class="min-h-11 w-full rounded-lg border border-slate-300 px-3"></div><div class="sm:col-span-3"><label for="company-street" class="mb-1 block text-sm font-semibold text-slate-700">Endereço</label><input id="company-street" name="street" maxlength="180" class="min-h-11 w-full rounded-lg border border-slate-300 px-3"></div><div><label for="company-number" class="mb-1 block text-sm font-semibold text-slate-700">Número</label><input id="company-number" name="number" maxlength="30" class="min-h-11 w-full rounded-lg border border-slate-300 px-3"></div><div><label for="company-complement" class="mb-1 block text-sm font-semibold text-slate-700">Complemento</label><input id="company-complement" name="complement" maxlength="120" class="min-h-11 w-full rounded-lg border border-slate-300 px-3"></div><div><label for="company-district" class="mb-1 block text-sm font-semibold text-slate-700">Bairro</label><input id="company-district" name="district" maxlength="120" class="min-h-11 w-full rounded-lg border border-slate-300 px-3"></div><div><label for="company-city" class="mb-1 block text-sm font-semibold text-slate-700">Cidade</label><input id="company-city" name="city" maxlength="120" class="min-h-11 w-full rounded-lg border border-slate-300 px-3"></div><div><label for="company-state" class="mb-1 block text-sm font-semibold text-slate-700">UF</label><input id="company-state" name="state" maxlength="2" class="min-h-11 w-full rounded-lg border border-slate-300 px-3 uppercase"></div><input type="hidden" name="country" value="BR"></div></section>
                <section><div class="flex items-center justify-between border-b border-slate-200 pb-2"><div><h3 class="text-lg font-bold text-slate-800">Contatos</h3><p class="mt-1 text-sm text-slate-500">Adicione quantas pessoas precisar. Elas também aparecerão no menu Contatos.</p></div><button type="button" data-add-company-contact class="rounded-lg border border-brand-200 px-3 py-2 text-sm font-bold text-brand-700 hover:bg-brand-50">+ Adicionar contato</button></div><div data-company-contact-list class="mt-4 grid gap-3"></div><p data-company-contact-empty class="rounded-lg border border-dashed border-slate-300 p-4 text-center text-sm text-slate-500">Nenhum contato adicionado ainda.</p></section>
                <section><h3 class="border-b border-slate-200 pb-2 text-lg font-bold text-slate-800">Observações</h3><textarea id="company-notes" name="notes" rows="4" maxlength="10000" class="mt-4 w-full rounded-lg border border-slate-300 px-3 py-2 outline-none focus:border-brand-500 focus:ring-2 focus:ring-brand-100" placeholder="Registre informações importantes sobre esta empresa"></textarea></section></div>
            <p class="mt-5 hidden rounded-lg bg-red-50 p-3 text-sm text-red-700" data-company-form-error role="alert"></p><div class="mt-7 flex justify-end gap-3"><button type="button" data-company-close class="rounded-lg border border-slate-200 px-4 py-2.5 text-sm font-bold text-slate-600 hover:bg-slate-50">Cancelar</button><button type="submit" data-company-submit class="rounded-lg bg-slate-900 px-4 py-2.5 text-sm font-bold text-white hover:bg-slate-700">Salvar empresa</button></div></form></dialog>
    </section>
</x-layouts.crm>
